      const skin = SKINS.find(function (s) { return s.id === id; });
      if (!skin) return false;
      const persist = !opts || opts.persist !== false;
      curSkinId = id;
      if (persist) saveSkin(id);
      const themeSvc = (typeof ctx.get === 'function' && ctx.get('theme')) || ctx.theme;
      if (themeSvc && themeSvc.overrideTokens) themeSvc.overrideTokens('dsh-anime-skins', buildTokens(skin));
      const cssId = 'dsh-anime-skins/style';
      const prev = document.querySelector('style[data-plugin-css="' + cssId + '"]');
      if (prev) prev.remove();
