            b.textContent = a.label;
            b.disabled = !a.run;
            b.style.cssText = 'display:block;width:100%;box-sizing:border-box;margin:1px 0;padding:7px 12px;border:none;border-radius:7px;background:transparent;color:' + (a.run ? fg : muted) + ';font-size:13px;text-align:left;cursor:' + (a.run ? 'pointer' : 'default') + ';white-space:nowrap';
            b.onmouseenter = function () { if (a.run) b.style.background = hover; };
            b.onmouseleave = function () { b.style.background = 'transparent'; };
